import{_ as s,o as a,c as t,ag as o}from"./chunks/framework.D2veAa-g.js";const m=JSON.parse('{"title":"典型信息系统架构模型","description":"","frontmatter":{"title":"典型信息系统架构模型"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/信息系统基础知识（第二版）/典型信息系统架构模型.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/信息系统基础知识（第二版）/典型信息系统架构模型.md","lastUpdated":null}'),i={name:"架构师 在线刷题/51CT0题库 章节练习/信息系统基础知识（第二版）/典型信息系统架构模型.md"};function n(r,l,e,c,u,g){return a(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="典型信息系统架构模型" tabindex="-1">典型信息系统架构模型 <a class="header-anchor" href="#典型信息系统架构模型" aria-label="Permalink to &quot;典型信息系统架构模型&quot;">​</a></h1><blockquote><p>共 16 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-电子政务的主要应用模式中不包括-。" tabindex="-1">Q1. 电子政务的主要应用模式中不包括（ ）。 <a class="header-anchor" href="#q1-电子政务的主要应用模式中不包括-。" aria-label="Permalink to &quot;Q1. 电子政务的主要应用模式中不包括（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 政府对政府(Government To Government)</li><li><strong>B.</strong> 政府对客户(Government To Customer)</li><li><strong>C.</strong> 政府对公务员(Government To Employee)</li><li><strong>D.</strong> 政府对企业(Government To Business)</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q2-电子商务系统中参与电子商务活动的实体包括-21-。" tabindex="-1">Q2. 电子商务系统中参与电子商务活动的实体包括（21）。 <a class="header-anchor" href="#q2-电子商务系统中参与电子商务活动的实体包括-21-。" aria-label="Permalink to &quot;Q2. 电子商务系统中参与电子商务活动的实体包括（21）。&quot;">​</a></h2><ul><li><strong>A.</strong> 客户、商户、银行和认证中心</li><li><strong>B.</strong> 客户、银行、商户和政府机构</li><li><strong>C.</strong> 客户、商户、银行和物流企业</li><li><strong>D.</strong> 客户、商户、政府和物流企业</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q3-国家和地方人口信息的采集、处理和利用-属于-的电子政务活动。" tabindex="-1">Q3. 国家和地方人口信息的采集、处理和利用，属于（）的电子政务活动。 <a class="header-anchor" href="#q3-国家和地方人口信息的采集、处理和利用-属于-的电子政务活动。" aria-label="Permalink to &quot;Q3. 国家和地方人口信息的采集、处理和利用，属于（）的电子政务活动。&quot;">​</a></h2><ul><li><strong>A.</strong> 政府对政府</li><li><strong>B.</strong> 政府对居民</li><li><strong>C.</strong> 居民对居民</li><li><strong>D.</strong> 居民对政府</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q4-与电子政务相关的行为主体主要有三个-即-政府的业务活动也主要围绕着这三个行为主体展开。" tabindex="-1">Q4. 与电子政务相关的行为主体主要有三个，即（ ），政府的业务活动也主要围绕着这三个行为主体展开。 <a class="header-anchor" href="#q4-与电子政务相关的行为主体主要有三个-即-政府的业务活动也主要围绕着这三个行为主体展开。" aria-label="Permalink to &quot;Q4. 与电子政务相关的行为主体主要有三个，即（ ），政府的业务活动也主要围绕着这三个行为主体展开。&quot;">​</a></h2><ul><li><strong>A.</strong> 政府、数据及电子政务系统</li><li><strong>B.</strong> 政府、企(事)业单位及中介</li><li><strong>C.</strong> 政府、服务机构及企事业单位</li><li><strong>D.</strong> 政府、企(事)业单位及公民</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q5-企业信息化涉及对企业管理理念的创新-按照市场发展的要求-对企业现有的管理流程重新整合-管理核心从对-请作答此空-的管理-转向对-的管理-并延伸到对企业技术创新、工艺设计、产品设计、生产制造过程的管理-进而还要扩展到对-的管理乃至发展到电子商务。" tabindex="-1">Q5. 企业信息化涉及对企业管理理念的创新，按照市场发展的要求，对企业现有的管理流程重新整合，管理核心从对（请作答此空）的管理，转向对（ ）的管理，并延伸到对企业技术创新、工艺设计、产品设计、生产制造过程的管理，进而还要扩展到对（ ）的管理乃至发展到电子商务。 <a class="header-anchor" href="#q5-企业信息化涉及对企业管理理念的创新-按照市场发展的要求-对企业现有的管理流程重新整合-管理核心从对-请作答此空-的管理-转向对-的管理-并延伸到对企业技术创新、工艺设计、产品设计、生产制造过程的管理-进而还要扩展到对-的管理乃至发展到电子商务。" aria-label="Permalink to &quot;Q5. 企业信息化涉及对企业管理理念的创新，按照市场发展的要求，对企业现有的管理流程重新整合，管理核心从对（请作答此空）的管理，转向对（ ）的管理，并延伸到对企业技术创新、工艺设计、产品设计、生产制造过程的管理，进而还要扩展到对（ ）的管理乃至发展到电子商务。&quot;">​</a></h2><ul><li><strong>A.</strong> 人力资源和物资</li><li><strong>B.</strong> 信息技术和知识</li><li><strong>C.</strong> 财务和物料</li><li><strong>D.</strong> 业务流程和数据</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q6-与电子政务相关的行为主体主要有三类-即政府、企-事-业单位及居民。因此-政府的业务活动也主要围绕着这三类行为主体展开。政府与政府、政府与企-事-业单位以及政府与居民之间的互动构成了5种不同的、却又相互关联的领域。其中缴交个税属于-1-领域-参加政府工程投标活动属于-2-领域。" tabindex="-1">Q6. 与电子政务相关的行为主体主要有三类， 即政府、企（事）业单位及居民。因此，政府的业务活动也主要围绕着这三类行为主体展开。政府与政府、政府与企（事）业单位以及政府与居民之间的互动构成了5种不同的、却又相互关联的领域。其中缴交个税属于 （1） 领域；参加政府工程投标活动属于 （2） 领域。 <a class="header-anchor" href="#q6-与电子政务相关的行为主体主要有三类-即政府、企-事-业单位及居民。因此-政府的业务活动也主要围绕着这三类行为主体展开。政府与政府、政府与企-事-业单位以及政府与居民之间的互动构成了5种不同的、却又相互关联的领域。其中缴交个税属于-1-领域-参加政府工程投标活动属于-2-领域。" aria-label="Permalink to &quot;Q6. 与电子政务相关的行为主体主要有三类， 即政府、企（事）业单位及居民。因此，政府的业务活动也主要围绕着这三类行为主体展开。政府与政府、政府与企（事）业单位以及政府与居民之间的互动构成了5种不同的、却又相互关联的领域。其中缴交个税属于 （1） 领域；参加政府工程投标活动属于 （2） 领域。&quot;">​</a></h2><ul><li><strong>A.</strong> 政府对企（事）业单位（G2B）</li><li><strong>B.</strong> 居民对政府（C2G）</li><li><strong>C.</strong> 企业对政府（B2G）</li><li><strong>D.</strong> 政府对居民（G2C）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q7-与电子政务相关的行为主体主要有三类-即政府、企-事-业单位及居民。因此-政府的业务活动也主要围绕着这三类行为主体展开。政府与政府、政府与企-事-业单位以及政府与居民之间的互动构成了5种不同的、却又相互关联的领域。其中缴交个税属于-1-领域-参加政府工程投标活动属于-2-领域。" tabindex="-1">Q7. 与电子政务相关的行为主体主要有三类， 即政府、企（事）业单位及居民。因此，政府的业务活动也主要围绕着这三类行为主体展开。政府与政府、政府与企（事）业单位以及政府与居民之间的互动构成了5种不同的、却又相互关联的领域。其中缴交个税属于 （1） 领域；参加政府工程投标活动属于 （2） 领域。 <a class="header-anchor" href="#q7-与电子政务相关的行为主体主要有三类-即政府、企-事-业单位及居民。因此-政府的业务活动也主要围绕着这三类行为主体展开。政府与政府、政府与企-事-业单位以及政府与居民之间的互动构成了5种不同的、却又相互关联的领域。其中缴交个税属于-1-领域-参加政府工程投标活动属于-2-领域。" aria-label="Permalink to &quot;Q7. 与电子政务相关的行为主体主要有三类， 即政府、企（事）业单位及居民。因此，政府的业务活动也主要围绕着这三类行为主体展开。政府与政府、政府与企（事）业单位以及政府与居民之间的互动构成了5种不同的、却又相互关联的领域。其中缴交个税属于 （1） 领域；参加政府工程投标活动属于 （2） 领域。&quot;">​</a></h2><ul><li><strong>A.</strong> 政府与政府（G2G）</li><li><strong>B.</strong> 政府对企（事）业单位（G2B）</li><li><strong>C.</strong> 企业对政府（B2G）</li><li><strong>D.</strong> 政府对居民（G2C）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q8-在制定企业信息化规划时-以下哪项陈述最准确-。" tabindex="-1">Q8. 在制定企业信息化规划时，以下哪项陈述最准确（ ）。 <a class="header-anchor" href="#q8-在制定企业信息化规划时-以下哪项陈述最准确-。" aria-label="Permalink to &quot;Q8. 在制定企业信息化规划时，以下哪项陈述最准确（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 企业信息化规划应完全独立于企业战略规划</li><li><strong>B.</strong> 企业信息化规划应建立在企业战略规划基础之上</li><li><strong>C.</strong> 企业信息化规划应优先于企业战略规划</li><li><strong>D.</strong> 企业信息化规划与企业战略规划没有直接关系</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q9-在企业信息化方法中-哪种方法的核心思想是-彻底的、根本性的-重新设计-。" tabindex="-1">Q9. 在企业信息化方法中，哪种方法的核心思想是&quot;彻底的、根本性的&quot;重新设计（ ）。 <a class="header-anchor" href="#q9-在企业信息化方法中-哪种方法的核心思想是-彻底的、根本性的-重新设计-。" aria-label="Permalink to &quot;Q9. 在企业信息化方法中，哪种方法的核心思想是&quot;彻底的、根本性的&quot;重新设计（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 核心业务应用方法</li><li><strong>B.</strong> 业务流程重构方法</li><li><strong>C.</strong> 信息系统建设方法</li><li><strong>D.</strong> 资源管理方法</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q10-企业信息化的目的不包括以下哪一项-。" tabindex="-1">Q10. 企业信息化的目的不包括以下哪一项（ ）。 <a class="header-anchor" href="#q10-企业信息化的目的不包括以下哪一项-。" aria-label="Permalink to &quot;Q10. 企业信息化的目的不包括以下哪一项（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 技术创新</li><li><strong>B.</strong> 管理创新</li><li><strong>C.</strong> 制度创新</li><li><strong>D.</strong> 产品创新</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q11-企业网站的发展历程中-哪一阶段注重将企业的各种应用系统、数据资源和互联网资源统一集成-提供企业的产品和用户信息-实现信息共享-。" tabindex="-1">Q11. 企业网站的发展历程中，哪一阶段注重将企业的各种应用系统、数据资源和互联网资源统一集成，提供企业的产品和用户信息，实现信息共享（ ）。 <a class="header-anchor" href="#q11-企业网站的发展历程中-哪一阶段注重将企业的各种应用系统、数据资源和互联网资源统一集成-提供企业的产品和用户信息-实现信息共享-。" aria-label="Permalink to &quot;Q11. 企业网站的发展历程中，哪一阶段注重将企业的各种应用系统、数据资源和互联网资源统一集成，提供企业的产品和用户信息，实现信息共享（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 企业网站</li><li><strong>B.</strong> 企业信息门户（EIP）</li><li><strong>C.</strong> 企业知识门户（EKP）</li><li><strong>D.</strong> 企业应用门户（EAP）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q12-企业应用集成-eai-中-哪种集成类型是将多个信息系统的界面集成在一起-为用户提供一个统一入口的集成方式-。" tabindex="-1">Q12. 企业应用集成(EAI)中，哪种集成类型是将多个信息系统的界面集成在一起，为用户提供一个统一入口的集成方式（ ）。 <a class="header-anchor" href="#q12-企业应用集成-eai-中-哪种集成类型是将多个信息系统的界面集成在一起-为用户提供一个统一入口的集成方式-。" aria-label="Permalink to &quot;Q12. 企业应用集成(EAI)中，哪种集成类型是将多个信息系统的界面集成在一起，为用户提供一个统一入口的集成方式（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 表示集成</li><li><strong>B.</strong> 数据集成</li><li><strong>C.</strong> 控制集成</li><li><strong>D.</strong> 业务流程集成</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q13-在电子政务中-以下哪种关系不属于主要行为主体之间的互动模式-。" tabindex="-1">Q13. 在电子政务中，以下哪种关系不属于主要行为主体之间的互动模式（ ）。 <a class="header-anchor" href="#q13-在电子政务中-以下哪种关系不属于主要行为主体之间的互动模式-。" aria-label="Permalink to &quot;Q13. 在电子政务中，以下哪种关系不属于主要行为主体之间的互动模式（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> G2G（政府对政府）</li><li><strong>B.</strong> G2B（政府对企业）</li><li><strong>C.</strong> C2C（居民对居民）</li><li><strong>D.</strong> G2C（政府对居民）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q14-企业信息化的核心是什么-。" tabindex="-1">Q14. 企业信息化的核心是什么（ ）。 <a class="header-anchor" href="#q14-企业信息化的核心是什么-。" aria-label="Permalink to &quot;Q14. 企业信息化的核心是什么（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 采用先进的硬件设备</li><li><strong>B.</strong> 运用信息技术进行知识挖掘和业务流程管理</li><li><strong>C.</strong> 建立完善的网络基础设施</li><li><strong>D.</strong> 实现全面的数据电子化</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q15-在电子政务活动中-政府向企业颁发各种营业执照、许可证、合格证和质量认证等属于哪种类型-。" tabindex="-1">Q15. 在电子政务活动中，政府向企业颁发各种营业执照、许可证、合格证和质量认证等属于哪种类型（ ）。 <a class="header-anchor" href="#q15-在电子政务活动中-政府向企业颁发各种营业执照、许可证、合格证和质量认证等属于哪种类型-。" aria-label="Permalink to &quot;Q15. 在电子政务活动中，政府向企业颁发各种营业执照、许可证、合格证和质量认证等属于哪种类型（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> G2G</li><li><strong>B.</strong> G2B</li><li><strong>C.</strong> B2G</li><li><strong>D.</strong> G2C</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q16-办公自动化系统的构成中-不包括-。" tabindex="-1">Q16. 办公自动化系统的构成中，不包括 （ ） 。 <a class="header-anchor" href="#q16-办公自动化系统的构成中-不包括-。" aria-label="Permalink to &quot;Q16. 办公自动化系统的构成中，不包括 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 计算机设备和办公设备</li><li><strong>B.</strong> 数据通信及网络设备</li><li><strong>C.</strong> 软件系统（包括系统软件和应用软件）</li><li><strong>D.</strong> 生产线自动化控制系统</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details>',50)])])}const h=s(i,[["render",n]]);export{m as __pageData,h as default};
